import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapHikingScheduleItem,
  mapHikingScheduleItemToBackAdd,
  mapHikingScheduleItemToBackUpdate,
} from '../@mappers/hikingSchedule.mapper';
import {
  IHikingScheduleAddDTO,
  IHikingScheduleDTO,
  IHikingScheduleUpdateDTO,
} from '../@types/hiking.backendTypes';
import { IHikingScheduleItem } from '../@types/hiking.baseTypes';

export const getHikingSchedule = async (id_hiking: number) => {
  const res = await get<IHikingScheduleDTO[]>('/ajax/hiking/shedule_list.php', { id_hiking });
  return res.map(mapHikingScheduleItem);
};

export const getHikingScheduleForDate = async (id_hiking: number, date: Date) => {
  const res = await get<IHikingScheduleDTO[]>('/ajax/hiking/shedule_list.php', {
    id_hiking,
    day: date.toISOString().substr(0, 10),
  });
  return res.map(mapHikingScheduleItem);
};

export const addHikingSchedule = async (
  id_hiking: number,
  scheduleItem: IHikingScheduleItem,
): Promise<IHikingScheduleItem> => {
  const data = mapHikingScheduleItemToBackAdd(id_hiking)(scheduleItem);
  const res = await post<{ id: number }, IHikingScheduleAddDTO>(
    '/ajax/hiking/shedule_add.php',
    data,
  ).then(handleApiError);
  return { ...scheduleItem, id: +res.id };
};

export const updateHikingSchedule = async (
  id_hiking: number,
  scheduleItem: IHikingScheduleItem,
): Promise<IHikingScheduleItem> => {
  const data = mapHikingScheduleItemToBackUpdate(id_hiking)(scheduleItem);
  await post<{ id: number }, IHikingScheduleUpdateDTO>('/ajax/hiking/shedule_edit.php', data).then(
    handleApiError,
  );
  return scheduleItem;
};
export const deleteHikingSchedule = async (id_hiking: number, id_hiking_schedule: number) => {
  const res = await post('/ajax/hiking/shedule_del.php', {
    id_hiking,
    id: id_hiking_schedule,
  }).then<{ success: boolean }>(handleApiError);
  return res.success;
};

export const switchScheduleDays = (id_hiking: number, d1: string, d2: string) => {
  return post('/ajax/hiking/shedule_switch_dates.php', { id_hiking, d1, d2 }).then(handleApiError);
};
